class NumberList {
  private items: number[] = [];
  add(n: number) { this.items.push(n); }
  get(index: number) { return this.items[index]; }
  size() { return this.items.length; }
}

const list = new NumberList();
for (let i = 0; i < list.size(); i++) {
  console.log(list.get(i));
}

class ShoppingCart {
  items: string[] = [];
  private position = 0;
  add(item: string) { this.items.push(item); }
  hasNext() { return this.position < this.items.length; }
  next() { return this.items[this.position++]; }
}

const cart = new ShoppingCart();
