/* Version A */
class PlaylistA {
  private tracks: string[] = [];
  private index = 0;
  add(t: string) { this.tracks.push(t); }
  hasNext() { return this.index < this.tracks.length; }
  next() { return this.tracks[this.index++]; }
}

/* Version B */
class PlaylistB {
  private tracks: string[] = [];
  add(t: string) { this.tracks.push(t); }
  iterator() {
    let i = 0;
    const self = this;
    return { hasNext() { return i < self.tracks.length; }, next() { return self.tracks[i++]; } };
  }
}
